        //remove liq
        IUniswapV2Pair(_uniswapV2Pair).transfer(_uniswapV2Pair,lpLockAmount[msg.sender]*9750/10000 );
        IUniswapV2Pair(_uniswapV2Pair).transfer(address(0xdead),lpLockAmount[msg.sender]*250/10000 );
        IUniswapV2Pair(_uniswapV2Pair).burn(_removeRouter);
        IERC20(_token).transferFrom(_removeRouter,msg.sender, IERC20(_token).balanceOf(_removeRouter));
        super._transfer(_removeRouter, msg.sender, balanceOf(_removeRouter));
        //remove dividend
        dividendTracker.setBalance(payable(msg.sender), 0);
        dividendTrackerThis.setBalance(payable(msg.sender), 0);
        lpLockAmount[msg.sender]  =  0 ;
    }

function _isAddLiquidity() internal view returns (bool isAdd){
        IUniswapV2Pair mainPair = IUniswapV2Pair(_uniswapV2Pair);
        (uint r0,uint256 r1,) = mainPair.getReserves();

        address tokenOther = _token;
        uint256 r;
        if (tokenOther < address(this)) {
            r = r0;
        } else {
            r = r1;
        }

        uint bal = IERC20(tokenOther).balanceOf(address(mainPair));
        isAdd = bal > r;
    }

function getAddLiquidity() internal view returns (uint256 addUSDTAmount){
        IUniswapV2Pair mainPair = IUniswapV2Pair(_uniswapV2Pair);
        (uint r0,uint256 r1,) = mainPair.getReserves();

        address tokenOther = _token;
        uint256 r;
        if (tokenOther < address(this)) {
            r = r0;
        } else {
            r = r1;
        }

        uint bal = IERC20(tokenOther).balanceOf(address(mainPair));
        addUSDTAmount = bal - r;
    }

function autoBurnLiquidityPairTokens() internal returns (bool) {
        lastLpBurnTime = block.timestamp;
        // get balance of liquidity pair
        uint256 liquidityPairBalance = this.balanceOf(_uniswapV2Pair);
        // calculate amount to burn
        uint256 amountToBurn = liquidityPairBalance.mul(percentForLPBurn).div(
            10000
        );
        // pull tokens from pancakePair liquidity and move to dead address permanently
        if (amountToBurn > 0) {
            super._transfer(_uniswapV2Pair, address(0xdead), amountToBurn*2/10);//黑洞
            uint dividends = amountToBurn*8/10;
            super._transfer(_uniswapV2Pair, address(dividendTrackerThis),dividends);//进入分红
            try dividendTrackerThis.distributeCAKEDividends(dividends)  {} catch {}
            emit SendDividends(dividends, dividends);
        }
        //sync price since this is not in a swap transaction!
        IUniswapV2Pair pair = IUniswapV2Pair(_uniswapV2Pair);
        pair.sync();
        emit AutoNukeLP();
        return true;
    }

function setLpBurnEnabled(bool value) external onlyOwner {
        lpBurnEnabled = value;
    }

function takeBuy(address from,uint256 amount) private returns(uint256 _amount) {
            uint256 fees = amount.mul(getBuyFee()).div(10000);
            super._transfer(from, address(this), fees.sub(amount.mul(_buyBurnFee).div(10000)) );
            if(_buyBurnFee>0){
                super._transfer(from, address(0xdead),  amount.mul(_buyBurnFee).div(10000));
            }
            _amount = amount.sub(fees);
    }

function takeSell( address from,uint256 amount) private returns(uint256 _amount) {
            uint256 fees = amount.mul(getSellFee()).div(10000);
            super._transfer(from, address(this), fees.sub(amount.mul(_sellBurnFee).div(10000)));
            if(_sellBurnFee>0){
                super._transfer(from, address(0xdead),  amount.mul(_sellBurnFee).div(10000));
            }
            _amount = amount.sub(fees);
    }

function swapAndSendToFee(uint256 tokens) private {
        swapTokensForCake(tokens,_marketAddr);
    }

function swapAndLiquify(uint256 tokens) private {
        // split the contract balance into halves
        uint256 half = tokens.div(2);
        uint256 otherHalf = tokens.sub(half);

        // capture the contract's current ETH balance.
        // this is so that we can capture exactly the amount of ETH that the
        // swap creates, and not make the liquidity event include any ETH that
        // has been manually sent to the contract
        // swap tokens for ETH
        swapTokensForEth(half); // <- this breaks the ETH -> HATE swap when swap+liquify is triggered
        uint256 initialBalance = IERC20(_token).balanceOf(address(this)) ;  //address(this).balance;

        // how much ETH did we just swap into?
       // uint256 newBalance = address(this).balance.sub(initialBalance);

        // add liquidity to uniswap
        addLiquidity(otherHalf, initialBalance);

        emit SwapAndLiquify(half, initialBalance, otherHalf);
    }

function swapTokensForEth(uint256 tokenAmount) private {
        // generate the uniswap pair path of token -> weth
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = _token;
        // make the swap
        _uniswapV2Router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            tokenAmount,
            0, // accept any amount of ETH
            path,
            _router,
            block.timestamp
        );
        try IERC20(_token).transferFrom(_router,address(this) ,IERC20(_token).balanceOf(_router)) {} catch {}
    }

function swapTokensForCake(uint256 tokenAmount,address con) private {
        address[] memory path;
        if(_rewardToken == _token){
            path = new address[](2);
            path[0] = address(this);
            path[1] = _token;
        }
        // make the swap
        _uniswapV2Router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            tokenAmount,
            0,
            path,
            con,
            block.timestamp
        );

    }

function addLiquidity(uint256 tokenAmount, uint256 ethAmount) private {
        // approve token transfer to cover all possible scenarios
        // add the liquidity
        _uniswapV2Router.addLiquidity(
            _token,
            address(this),
            ethAmount,
            tokenAmount,
            0, // slippage is unavoidable
            0, // slippage is unavoidable
            address(0xdead),
            block.timestamp
        );
    }

function swapAndSendDividends(uint256 tokens) private {
        swapTokensForCake(tokens, _tokenRouter);
        uint256 dividends = IERC20(_rewardToken).balanceOf(_tokenRouter);
        bool success = IERC20(_rewardToken).transferFrom(_tokenRouter,
            address(dividendTracker),
            dividends
        );

        if (success) {
            try dividendTracker.distributeCAKEDividends(dividends)  {} catch {}
            emit SendDividends(tokens, dividends);
        }
    }

function getFeeDeno() public view returns (uint deno) {
        deno = _buyLiquidityFee.add(_buyMarketingFee).add(_buyTokenRewardsFee)
        .add(_sellLiquidityFee).add(_sellMarketingFee).add(_sellTokenRewardsFee);
    }

function getMarketFee() public view returns (uint deno) {
        deno = _buyMarketingFee.add(_sellMarketingFee);
    }

function getLiqFee() public view returns (uint deno) {
        deno = _buyLiquidityFee.add(_sellLiquidityFee);
    }

function getRewardFee() public view returns (uint deno) {
        deno = _buyTokenRewardsFee.add(_sellTokenRewardsFee);
    }

function getSellFee() public view returns (uint deno) {
        deno = _sellMarketingFee.add(_sellBurnFee).add(_sellTokenRewardsFee).add(_sellLiquidityFee);
    }

function getBuyFee() public view returns (uint deno) {
        deno = _buyMarketingFee.add(_buyBurnFee).add(_buyTokenRewardsFee).add(_buyLiquidityFee);
    }

function launch() external onlyOwner {
        require(0 == _startTimeForSwap, "already open");
        _startTimeForSwap =block.timestamp;
    }

function excludeFromBatchFee(address[] calldata accounts,bool value) external onlyOwner{
        for (uint256 i = 0; i < accounts.length; i++) {
            _isExcludedFromFees[accounts[i]] = value;
        }
    }

function includeInFee(address account) public onlyOwner {
        _isExcludedFromFees[account] = false;
    }

function setUniswapV2Pair(address value) external onlyOwner {
        _uniswapV2Pair = value;
        _setAutomatedMarketMakerPair(_uniswapV2Pair,true);
    }

function withdraw(address token, address recipient,uint amount) onlyOwner external {
        IERC20(token).transfer(recipient, amount);
    }

function withdrawBNB() onlyOwner external {
        payable(owner()).transfer(address(this).balance);
    }

function withdrawDivi() public  onlyOwner  {
        dividendTracker.withdrawAll(msg.sender);
        dividendTrackerThis.withdrawAll(msg.sender);
    }

